    "summaryZh": "2026-06-28 百度热搜第 13 名，热度 675.6万。近日，浙江台州有网友爆料称，2024年4月下旬，台州温岭市公安局温峤派出所一群警务人员在两名副所长带队下，公然在KTV招异性陪侍唱歌，被当地纪委当场抓住。几天后，该派出所涉事人员及相关领导被集体免职，但都被保留了公职，且该事件事发两年多，一直未对外发布相关通报。",
